Hier ist ein Beispiel-Code für ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

int main() {
    // Definieren des Such-Wortes
    std::string search_word;

    // Eingabe des Such-Wortes
    std::cout << "Bitte das Suchwort eingeben: ";
    std::cin >> search_word;

    // Öffnen der Textdatei
    std::ifstream input_file("dateiname.txt");

    if (!input_file) {
        std::cerr << "Fehler beim Öffnen der Datei!" << std::endl;
        return 1;
    }

    // Speichern der Anzahl der Vorkommen
    unsigned int count = 0;

    // Speichern der letzten Zeile (optional, damit das Programm am Ende die gesuchten Vorkommen ausgibt)
    std::string last_line;

    // Hash-Tabellen zur schnellen Sucht nach dem Suchwort
    std::unordered_map<std::string, unsigned int> word_counts;

    // Iterieren über die Datei Zeile für Zeile
    std::string line;
    while (getline(input_file, line)) {
        // Trennen der Zeile in Wörter
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            // Suchen des Such-Wortes im aktuellen Wort
            if (word == search_word) {
                // Inkrementieren der Anzahl der Vorkommen
                ++count;

                // Speichern des aktuellen Wortes im Hash-Objekt
                word_counts[word]++;
            }
        }

        // Speichern der letzten Zeile (optional)
        last_line = line;
    }

    // Schließen der Datei
    input_file.close();

    // Ausgabe der Anzahl der Vorkommen des Such-Wortes
    std::cout << "Das Suchwort '" << search_word << "' kommt " << count << " mal vor." << std::endl;

    // Ausgabe der Anzahl der Vorkommen jedes Wortes in der Datei (optional)
    if (!word_counts.empty()) {
        std::cout << "Anzahl der Vorkommen jedes Wortes in der Datei:" << std::endl;
        for (const auto& [word, count] : word_counts) {
            std::cout << "\t'" << word << "': " << count << std::endl;
        }
    }

    // Ausgabe der letzten Zeile (optional)
    if (!last_line.empty()) {
        std::cout << "Letzte Zeile: " << last_line << std::endl;
    }

    return 0;
}
